/**
 * Картинка с цифрами часов вместо TextClock (шрифты из ресурсов приложения лаунчер не загружает):
 * [clock] — цифры, место которых она занимает, [format] — h (часы), m (минуты), t («ч:мм»),
 * w («чч» над «мм»), s («чч мм»), [align] — для выравниваемых цифр s/c/e (начало, центр, конец), иначе «.».
 */
class TimeImage(val image: Int, val clock: Int, val format: Char, val align: Char)

object TimeImages {
    private val map: Map<Int, TimeImage> = listOf(
        TimeImage(R.id.tih_m_hours_al_s, R.id.m_hours_al, 'h', 's'),
        TimeImage(R.id.tih_m_hours_al_c, R.id.m_hours_al, 'h', 'c'),
        TimeImage(R.id.tih_m_hours_al_e, R.id.m_hours_al, 'h', 'e'),
        TimeImage(R.id.tim_a_minutes_al_s, R.id.a_minutes_al, 'm', 's'),
        TimeImage(R.id.tim_a_minutes_al_c, R.id.a_minutes_al, 'm', 'c'),
        TimeImage(R.id.tim_a_minutes_al_e, R.id.a_minutes_al, 'm', 'e'),
        TimeImage(R.id.tit_m_time, R.id.m_time, 't', '.'),
        TimeImage(R.id.tis_m_time, R.id.m_time, 's', '.'),
        TimeImage(R.id.tih_m_hours, R.id.m_hours, 'h', '.'),
        TimeImage(R.id.tim_m_minutes, R.id.m_minutes, 'm', '.'),
        TimeImage(R.id.tit_o_time, R.id.o_time, 't', '.'),
        TimeImage(R.id.tit_m_time_al_s, R.id.m_time_al, 't', 's'),
        TimeImage(R.id.tit_m_time_al_c, R.id.m_time_al, 't', 'c'),
        TimeImage(R.id.tit_m_time_al_e, R.id.m_time_al, 't', 'e'),
        TimeImage(R.id.tim_a_minutes, R.id.a_minutes, 'm', '.'),
    ).associateBy { it.image }

    operator fun get(id: Int): TimeImage? = map[id]
}

